int a[102][102], n, m;
int fill(int i, int j) {
    if (i < 1 || i > n || j < 1 || j > m || a[i][j] != 1) return 0;
    a[i][j] = 2;
    return 1 + fill(i - 1, j) + fill(i + 1, j) + fill(i, j - 1) + fill(i, j + 1);
}
int main() {
    int best = 0;
    cin >> n >> m;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) cin >> a[i][j];
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (a[i][j] == 1) {
                int t = fill(i, j);
                if (t > best) best = t;
            }
    cout << best;
    return 0;
}

