        if (a != b) {
            t[a] = b;
            comp--;
        }
    }
    sort(e + k, e + m, cmp);
    long long cost = 0;
    for (int i = k; i < m; i++) {
        int a = rad(e[i].u), b = rad(e[i].v);
        if (a != b) {
            t[a] = b;
            comp--;
            cost += e[i].c;
        }
    }
