#include <iostream>
using namespace std;
const long long MOD = 1000000007;
const int N = 1000001;
long long f[N], inv[N];
long long putere(long long a, long long e) {
    long long r = 1;
    a %= MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    f[0] = 1;
    for (int i = 1; i < N; i++) f[i] = f[i - 1] * i % MOD;
    inv[N - 1] = putere(f[N - 1], MOD - 2);
    for (int i = N - 1; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
    int q, n, k;
    cin >> q;
    while (q--) {
        cin >> n >> k;
        if (k > n) cout << 0 << "\n";
        else cout << f[n] * inv[k] % MOD * inv[n - k] % MOD << "\n";
    }
    return 0;
}

