        bestSt = z2 - z1 - 1;
        bestDr = 0;
    }
    for (int k = 0; k < bestSt; k++) cout << "1 ";
    cout << "0";
    for (int k = 0; k < bestDr; k++) cout << " 1";
    return 0;
}

